CREATE TABLE "emails" (   id TEXT PRIMARY KEY,   from_addr TEXT NOT NULL,   to_addr TEXT NOT NULL,   subject TEXT NOT NULL,   body TEXT NOT NULL,   spam_score INTEGER NOT NULL,   risk_score INTEGER NOT NULL,   is_spam INTEGER NOT NULL,   received_at TEXT NOT NULL,   dkim_result TEXT NOT NULL,   spf_result TEXT NOT NULL,   dmarc_result TEXT NOT NULL,   arc_result TEXT NOT NULL,   client_ip TEXT NOT NULL,   urls_json TEXT NOT NULL,   attachments_json TEXT NOT NULL )
